      "week": 35,
      "unit": "Unit 9 · State/Local Research Capstone and Grade 5 Bridge",
      "title": "State and Local History Research Capstone",
      "essentialQuestion": "How can I build a defensible historical investigation using multiple sources and disciplinary tools?",
      "keyIdea": "The Grade 4 capstone requires a focused state/local question, chronology, geography, multiple source types, primary evidence when appropriate, multiple perspectives, economic/civic context, citations, revision, and oral defense.",
      "vocabulary": [
        {
          "term": "research question",
          "definition": "a focused question guiding an investigation"
        },
        {
          "term": "thesis",
          "definition": "a central claim supported by evidence"
        },
        {
          "term": "bibliography",
          "definition": "a list of sources used in research"
        },
        {
          "term": "oral defense",
          "definition": "spoken explanation and response to questions about research choices and conclusions"
        }
      ],
      "constructedResponse": "Respond to the essential question — \"How can I build a defensible historical investigation using multiple sources and disciplinary tools?\" — with a clear claim, at least three specific pieces of evidence or examples, and reasoning that explains how the evidence supports the claim. Include a limitation, counterpoint, or unresolved question when appropriate.",
      "lessons": [
        {
          "day": "Monday",
          "title": "Inquiry, Vocabulary & Historical Context",
          "objective": "Frame a focused inquiry and build accurate context for state and local history research capstone.",
          "activity": "Choose a teacher-approved state/local history or civic question that protects privacy and avoids partisan advocacy.",
          "evidence": "Inquiry question, context notes, chronology/map organizer, or vocabulary evidence."
        },
        {
          "day": "Tuesday",
          "title": "Disciplinary Tool & Analysis",
          "objective": "Apply a historical, geographic, civic, economic, or quantitative tool to the week's inquiry.",
          "activity": "Build a source plan with at least five sources from at least three source types, including map/data and primary/official evidence when appropriate.",
          "evidence": "Annotated map/timeline/data model/comparison with observations and reasoning."
        },
        {
          "day": "Wednesday",
          "title": "Primary & Secondary Source Laboratory",
          "objective": "Analyze source creator, date, purpose, audience, evidence, perspective, corroboration, and limits.",
          "activity": "Draft a thesis, timeline/map, evidence table, counterevidence/limitations note, and bibliography.",
          "evidence": "Source-analysis record with citation, evidence, inference, corroboration, and uncertainty."
        },
        {
          "day": "Thursday",
          "title": "Synthesis, Argument, Deliberation, or Informed Action",
          "objective": "Develop and communicate a defensible conclusion, comparison, interpretation, or recommendation.",
          "activity": "Create a report, exhibit, map story, documentary script, civic memo, or presentation and complete a short oral defense.",
          "evidence": "Evidence paragraph/essay, exhibit, deliberation record, map story, civic/economic recommendation, or presentation."
        },
        {
          "day": "Friday",
          "title": "Mastery, Constructed Response, Corrections & Portfolio",
          "objective": "Demonstrate at least 80% objective mastery and defend understanding in writing.",
          "activity": "Complete the randomized open-book subject check, answer the constructed evidence response, review/correct if below 80%, take a fresh randomized form after remediation, and archive one strong artifact.",
          "evidence": "Best objective score + constructed response + correction note when needed + portfolio artifact and reflection."
        }
      ],
